def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev_bids = []
    urgent_opponents = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('budget', 0) >= bid:
                    strong_prev_bids.append(bid)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.28))

    slots_est = max(1, int(supply / WATER_REQ))
    pressure = len(alive) + 1 - slots_est

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0
    strong_high = max(strong_prev_bids) if strong_prev_bids else highest_prev

    if pressure <= 0:
        base = DAILY_SALARY * 0.32
    elif pressure == 1:
        base = DAILY_SALARY * 0.48
    else:
        base = DAILY_SALARY * 0.62

    if supply >= 23:
        base -= 8
    elif supply <= 17:
        base += 8

    if hp <= 2:
        base = max(base, strong_high + 4.0, DAILY_SALARY * 0.9)
    elif no_water_days >= 1:
        base = max(base, strong_high + 2.0, DAILY_SALARY * 0.78)
    elif hp >= 7 and supply >= 20:
        base -= 6

    if highest_prev >= 100:
        if hp > 4 and no_water_days == 0:
            base = min(base, DAILY_SALARY * 0.42)
        else:
            base = max(base, DAILY_SALARY * 0.88)
    elif highest_prev > 0:
        target = max(avg_prev + 1.5, strong_high + 1.0)
        if hp >= 6 and no_water_days == 0 and supply >= 20:
            target -= 4
        base = max(base, target)

    if urgent_opponents >= 2 and pressure >= 1:
        base += 4

    if day >= 8:
        if hp >= 5:
            base -= 3
        else:
            base += 5

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    affordable = max(0.0, budget - reserve_floor)
    bid = min(base, budget)
    if affordable > 0:
        bid = min(bid, max(affordable, DAILY_SALARY * 0.22))

    if hp <= 1:
        bid = min(budget, max(bid, DAILY_SALARY * 0.98))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev['bid'] > 0:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 1.25:
            base_bid = highest_prev_bid + 5.0
        elif highest_prev_bid >= DAILY_SALARY * 1.1:
            base_bid = highest_prev_bid + 2.0
        else:
            base_bid = max(DAILY_SALARY * 0.95, avg_prev_bid * 1.05)

    scarcity_multiplier = 1.0
    total_water_needed_for_all = (num_alive_opponents + 1) * WATER_REQ

    if day_context['supply'] < total_water_needed_for_all * 0.5:
        scarcity_multiplier = 1.15
    elif day_context['supply'] < total_water_needed_for_all * 0.75:
        scarcity_multiplier = 1.05

    base_bid *= scarcity_multiplier

    current_bid = base_bid

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        current_bid = max(current_bid, DAILY_SALARY * 1.4)
    elif my_status['hp'] <= 4:
        current_bid = max(current_bid, DAILY_SALARY * 1.15)
    elif my_status['hp'] >= 7 and day_context['day'] < EPISODE_DAYS - 2:
        current_bid = min(current_bid * 0.9, DAILY_SALARY * 1.0)
        current_bid = max(current_bid, DAILY_SALARY * 0.85)
    else:
        current_bid = max(current_bid, DAILY_SALARY * 1.0)

    final_bid = max(0.0, min(current_bid, my_status['budget']))
    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        # No history, conservative
        if hp <= 2 or no_water_days >= 2:
            return min(budget, DAILY_SALARY * 0.9)
        else:
            return min(budget, DAILY_SALARY * 0.5)

    avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)
    max_yesterday_bid = max(yesterday_bids)

    # Adjust based on urgency
    if hp <= 3 or no_water_days >= 1:
        # Need water urgently, bid aggressively but not exceed max_yesterday_bid much
        target = max(avg_yesterday_bid, DAILY_SALARY * 0.8)
        # Ensure we can win if they repeat same
        bid = min(budget, target + 1.0)
    else:
        # Healthy, conserve budget
        # Bid slightly below average to let others waste money
        bid = min(budget, max(DAILY_SALARY * 0.4, avg_yesterday_bid - 10.0))

    # Ensure minimum bid to avoid starvation if supply is low
    if supply == WATER_REQ:
        bid = max(bid, DAILY_SALARY * 0.7)

    # Cap at budget
    return min(budget, int(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer pressure
    yesterday_bids = []
    yesterday_pressures = []  # (opp_id, bid, hp_after)
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)
            yesterday_pressures.append((opp_id, b_val, prev.get('hp_after', None)))

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Estimate how many water units are likely to be contested.
    # In these games, higher bids generally correlate with securing water.
    # We'll set a target bid level based on supply scarcity.
    # supply is typically 15..25; map to a scarcity factor.
    scarcity = 0.0
    try:
        scarcity = (25.0 - float(supply)) / 10.0  # 0 at 25, 1 at 15
    except Exception:
        scarcity = 0.5

    # Base bid: if we are healthy, don't overpay; if low hp / many no-water days, bid more.
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * (0.75 + 0.15 * scarcity)
    elif hp <= 4:
        base = DAILY_SALARY * (0.6 + 0.1 * scarcity)
    else:
        base = DAILY_SALARY * (0.45 + 0.1 * scarcity)

    # Exploit yesterday: Alex/Cindy burned budgets with ~100+ bids; Bob survived with ~87.
    # So we avoid matching the very high bids unless necessary.
    # If opponents were bidding extremely high, we must raise to contest.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Emergency contest: bid near the high pressure but cap to budget.
        target = min(budget, highest_prev_bid + 2.0)
    else:
        # Otherwise, bid around base but slightly above the average of yesterday to steal wins.
        # If yesterday average was already high, nudge upwards; if low, keep it moderate.
        if avg_prev_bid > 0:
            target = base
            # If avg pressure is close, add a small premium.
            if avg_prev_bid >= DAILY_SALARY * 0.55:
                target = max(target, avg_prev_bid + 1.5)
            # If avg pressure is low, don't overpay.
            if avg_prev_bid < DAILY_SALARY * 0.5:
                target = min(target, DAILY_SALARY * 0.55 + 10.0 * scarcity)
        else:
            target = base

        # Small extra if many opponents appear to have bid non-trivially yesterday.
        nontrivial_count = 0
        for b in yesterday_bids:
            if b >= DAILY_SALARY * 0.45:
                nontrivial_count += 1
        if nontrivial_count >= 2:
            target = target + 5.0

        target = min(target, budget)

    # Ensure we bid at least a minimal amount if budget allows, to avoid guaranteed loss.
    min_reasonable = min(budget, DAILY_SALARY * 0.25)
    if target < min_reasonable:
        target = min_reasonable

    # Final clamp: can't exceed budget.
    if target > budget:
        target = budget

    return float(target)
